-- GENERATED by `wfj generate` from data/gossip/gossip-32.jsonl. Do not edit: `wfj validate` regenerates and diffs it.
local _, WFJ = ...
WFJ.Data.add("gossip", {
  ["3207a0185ac4f321"] = { "Vuoi imparare l'arte della guerra, {race}? Hai sbagliato posto.", "." },
  ["320f97b67cb435d3"] = { "Io punto sui goblin! E se hai un po' di sale in zucca, ci punti anche tu!", "." },
  ["32142b6c2ed2b0e3"] = { "{name} conquista la fucina! Se nessuno la contende, l'⟦Alliance=Alleanza⟧ la controllerà fra 1 minuto!", "." },
  ["3216458932daa1eb"] = { "PAESANO OLTREPASSA LINEA.", "." },
  ["321b6cb43162b123"] = { "I loro spiriti sono rinvigoriti! I grifoni sono pronti a colpire! Venite, soldati! Venite al mio fianco!", "." },
  ["321e92ca8480ae5d"] = { "%s strappa con violenza l'⟦Gloom Weed=Erba Tenebrosa⟧ dal terreno.", "." },
  ["32236632d38805d7"] = { "Sono pezzi davvero belli, {name}. La maestria e la cura messe nel farli mostrano che hai scelto di dedicarti completamente a questi compiti.\n\nHai soddisfatto le mie richieste, e con esse arriva la tua ricompensa. La conoscenza per fare le vesti di Cuoio Selvatico ora è tua!", "." },
  ["32298cbc7ee603e9"] = { "Ben fatto, Edward e Tyler. State procedendo molto bene nel vostro addestramento. Presto metteremo di nuovo alla prova il vostro coraggio.", "." },
  ["3229c05b08063142"] = { "Informazioni sul ⟦Blood of Heroes=Sangue degli Eroi⟧.", "." },
  ["322b30a43755d7f7"] = { "Ti chiedo scusa, Lady Prestor. Non era mia intenzione.", "." },
  ["3232dba57d8669a7"] = { "Commercio! Lo bramo!", "." },
  ["32342e57af1668c9"] = { "È bene che tu voglia onorare le tue prede facendo buon uso dei loro corpi. Trova Thuwd dentro la Kodohide Leatherworks, al centro del Varcolargo.", "." },
  ["32382afe8e816a0e"] = { "Oh no... Mist... che cos'è successo...?", "." },
  ["323bc67b3f3c98d7"] = { "Sei tornat<o/a>, {name}. Devi raccontarmi tutto quello che hai scoperto. Ma prima occupiamoci della tua ricompensa.", "." },
  ["324b7b29c7468979"] = { "Che sia l'ultimo!", "." },
  ["324ebeeb710c5cca"] = { "Beh, così non va proprio. La creatura è troppo piccola. Vediamo cosa farà il terzo lotto di Keever.", "." },
  ["3255054026db4fdd"] = { "Dammi gli arcani e creerò l'amalgama, mortale.", "." },
  ["325e5e8316e2058e"] = { "Continui a sfogliare il diario in cerca di qualsiasi informazione che possa aiutarti a trovare lo scrigno rubato.\n\nVerso le ultime pagine del libro, a matita rossa, vedi un'annotazione di James sul margine della pagina. Dice: \"Vecchia casa vicino al ⟦Stone Cairn Lake=Lago del Memoriale⟧... gli gnoll saranno perfetti come guardie del corpo.\"\n\nNiente fa pensare che lo scrigno sia lì, ma non sembrano esserci altri indizi.", "." },
  ["326218e00e0533a1"] = { "Cerco addestramento per cavalcare un destriero.", "." },
  ["32822700582dd8bb"] = { "Incursione di trogg! Difendimi mentre chiudo la breccia con un'esplosione!", "." },
  ["3282b1c8af8ddbd8"] = { "Sta' in guardia, {class}. Rispetta le nostre usanze, o una maledizione cadrà su di te e sui tuoi.", "." },
  ["32836098a76f0321"] = { "La lama e Mograine erano un'unica entità. Capisci? Questo atto corruppe la lama e portò alla corruzione dello stesso Mograine, divenuto un cavaliere della morte di Kel'Thuzad. Giurai che, se la vita mi fosse stata risparmiata, avrei smascherato gli autori di questo crimine atroce. Per due giorni rimasi sotto il marciume e il contagio del Flagello, raccogliendo quante più forze possibile per fuggire dalla città rasa al suolo.", "." },
  ["328486f36e32d5f9"] = { "Ho perso il mio talismano e me ne serve uno nuovo, Jin'rokh.", "." },
  ["32855a42b3ada022"] = { "Plucky non vuole che Tirth sappia che è ancora nelle Distese Salate, così si è trasformato in un pollo!\n\nSe trovi Plucky, fagli cenno di avvicinarsi. Forse uscirà allo scoperto.", "." },
  ["32895ea648c170c1"] = { "Ben <trovato/trovata>, <maestro/maestra> di canna e mulinello! Se te la senti di misurarti con i migliori pescatori del mondo, allora ascolta bene! Proprio questa domenica a Rovotorto si terrà una gara in cui verrà scelto il maestro pescatore!", "." },
  ["3295e6aff0be25e5"] = { "Sia lodata la Luce, sei qui! A questo punto accetterei aiuto anche da un ogre a due teste.\n\nLa città è stata invasa dai trogg! I tentativi di sterminarli hanno provocato una contaminazione di massa. Ma c'è ancora speranza.\n\nI nostri scienziati evacuati a ⟦Ironforge=Forgiardente⟧ stanno lavorando a una cura per la malattia da radiazioni. Nel frattempo, se puoi aiutarmi a fermare l'invasione dei trogg, forse la città potrà essere riconquistata.", "." },
  ["3299d270e9bb0e37"] = { "Torna da me con un lavoro così pietoso e ti rispedirò a casa in una scatoletta di ferro temprata nell'urina di capra. Ora va' da quell'idiota di Ug'thok, è più adatto alle tue esigenze.", "." },
  ["32a08901439cc790"] = { "La Madre Terra vegli su di noi, al riparo della notte come di giorno. Che questo fuoco illumini i nostri corpi e i nostri spiriti e ci ricordi i nostri onorati antenati, sempre presenti a guidare il nostro cammino.", "." },
  ["32a56220c22d9fa4"] = { "Chi osa disturbarmi? Muori, {name}!", "." },
  ["32b2bd98fb20785a"] = { "Uccidi!", "." },
  ["32b39f0cbb9de4d1"] = { "Flagello nelle fogne! Ci serve aiuto!", "." },
  ["32b85fb6126a4c94"] = { "Dov'è l'istruttore di ingegneria?", "." },
  ["32cdf8ac2c8a34da"] = { "<Il primo maresciallo Chambers ringhia.>\n\nQuindi sei tu la marmaglia che ha aiutato Didier a portare qui le provviste tutte intere? Dove sono gli altri? So che dovete essere di più. I fifoni come te di solito girano in branchi enormi.\n\nBah, dammi quel dannato documento così posso firmarlo.", "." },
  ["32d9caabf53b3fc3"] = { "Uccido l'uomo sul posto, come il mio signore si aspetterebbe da me, perché non è altro che un ladro e un bugiardo.", "." },
  ["32e1cc574f00cc48"] = { "Scacceremo i nostri nemici da ⟦Silverpine=Pinargento⟧, poi porteremo la marea della guerra fino alla loro capitale!", "." },
  ["32e43d2def01efa7"] = { "Vorrei esserci stato per vedere la faccia della bestia quando le hai inferto il colpo mortale, {name}.", "." },
  ["32eeca77d1727f7c"] = { "L'erba è morbida e rigogliosa. L'aria è fresca, piena di luce e di canti. Tutto ciò che ho visto fa pensare che Teldrassil sia un sogno diventato realtà. Perché, allora, il mio cuore è pieno di cattivi presentimenti?", "." },
  ["32f3f833710ee8d6"] = { "Non rivolgermi la parola nella tua lingua volgare! Solo Idraxis riesce a sopportarla.", "." },
})
